-- GENERATED by `wfj generate` from data/gossip/gossip-9a.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["9a0279888f46dca9"] = { "Vuoi aiutare i ⟦The Defilers=Profanatori⟧ nella loro lotta contro la ⟦The League of Arathor=Lega di Arathor⟧ nel ⟦Arathi Basin=Bacino d'Arathi⟧? Molto bene, allora dovresti chiedere aiuto a Martin Lindsey. Cercalo alle Pozze delle Visioni.", "." },
  ["9a02b23864cd184c"] = { "Ehi, Pratt, puoi insegnarmi di nuovo a fare gli ⟦Wild Leather Shoulders=Spallacci di Cuoio Selvatico⟧?", "." },
  ["9a052ff2e9187b27"] = { "⟦Desolace=Desolanda⟧ non è una terra gentile: naga, giganti, satiri, la Legione Infuocata... tutti loro, e i clan di centauri in guerra tra loro, rendono la regione pericolosa se non stai attent<o/a>.\n\nCome ti ho detto, metterà alla prova non solo la tua forza e la tua astuzia, ma anche la tua pazienza. Sta' in guardia in quelle terre, {name}.", "." },
  ["9a11adb455fe5b1e"] = { "Redpath! La tua vita finisce qui e ora!", "." },
  ["9a14b650f68e20d9"] = { "...troppo silenzio.", "." },
  ["9a153a627860485a"] = { "E l'⟦Alliance=Alleanza⟧, Rend?", "." },
  ["9a18e2477c5b156f"] = { "Devi aver raggiunto il livello Osannato con i nani di ⟦Ironforge=Forgiardente⟧ prima che ti insegni l'Equitazione, {class}.", "." },
  ["9a1ae9538ed50f60"] = { "Buongiorno, <cittadino/cittadina>. Come posso aiutarti?", "." },
  ["9a214499f6f537a9"] = { "I maghi si riuniscono nel Wizard's Sanctum, nel ⟦Mage Quarter=Quartiere dei Maghi⟧. Gran bella torre hanno lì. Al confronto le nostre caserme sembrano tuguri di contadini.", "." },
  ["9a22f6e6dad98dd1"] = { "Come procede la ricerca delle vesti, {name}? Le hai create da te? Trovo che un tocco personale renda ancora più dolce infondere la magia. Ti dà un maggior senso di soddisfazione. Ma capisco se scegli la via più rapida e te le fai fare da altri: c'è del merito anche in una simile... ambizione.", "." },
  ["9a24dca6f0bcdc8f"] = { "Parlami delle spedizioni che potrei esplorare.", "." },
  ["9a3af1f39dc2f106"] = { "Informazioni sulle Pezze Consumate dell'Abominio.", "." },
  ["9a3ca8befb323216"] = { "Ora posizionerò la ruota... per proteggerti dal male.", "." },
  ["9a42298525316ba8"] = { "Chi controlla il ⟦Iceblood Graveyard=Cimitero di Brinarossa⟧?", "." },
  ["9a487814cd7816d6"] = { "Il Culto? Sono fanatici e assassini. Credono che siamo puniti per qualche peccato non meglio specificato. In realtà, chi li guida sono opportunisti rimasti da un ambiguo ordine di cosiddetti \"sacerdoti\" di Al'Akir, il Signore del Vento. \r\n\nOra si trovano nella posizione di usare la paura del nostro popolo come un'arma per consolidare il proprio potere... e non hanno perso tempo.", "." },
  ["9a4d3f43f0bf0f42"] = { "Terrai tutte le dita delle mani e dei piedi, non preoccuparti.", "." },
  ["9a503bd96992a4f4"] = { "Allora vuoi reimparare ciò che hai dimenticato, eh? O magari imparare ciò che non ti è mai stato insegnato? Ho proprio quello che fa per te, {name}. Vicino al Porto degli Spargifumo, a est, troverai nella capanna di Narain un libro magico intitolato \"Soothsaying for Dummies\". Dagli una lettura.\n\n<Nixx ti fa l'occhiolino.>\n\nTroverai tutto ciò che ti serve sapere, e anche di più...", "." },
  ["9a50841d70422a15"] = { "Ho perso il talismano e me ne serve uno nuovo, Al'tabim.", "." },
  ["9a559e46a0bbd80f"] = { "{class}, mi servono altri lingotti di rame! Alle ⟦Gates of Ahn'Qiraj=Porte di Ahn'qiraj⟧ si prepara una guerra e ci servono provviste! L'⟦Alliance=Alleanza⟧ ha raccolto $1997w lingotti di rame e ce ne servono $1998w in tutto. Se non li ottengo, ci rimetterò la testa!", "." },
  ["9a586b8a9657c819"] = { "%s fissa con avidità un ⟦Deeprun Rat=Ratto degli Abissi⟧.", "." },
  ["9a595f3bbd129e0f"] = { "Agghhhh! Non... esultate! La vostra vittoria è vana, perché tornerò con poteri che non potete nemmeno immaginare!", "." },
  ["9a5ac926c2e60391"] = { "Salute, {name}. Sono il dottor Gustaf VanHowzen, primario di chirurgia traumatologica del Pronto Soccorso dell'⟦Alliance=Alleanza⟧.", "." },
  ["9a5ebf02511b9c15"] = { "%s scaglia lo Scettro delle Sabbie Mutevoli contro la barriera, mandandola in frantumi.", "." },
  ["9a72303764054626"] = { "Grazie per il tuo tempo, Lady Prestor.", "." },
  ["9a806bd5e521d60f"] = { "Ho sentito che gli ultimi preparativi vengono spediti a ⟦Silithus=Silitus⟧ e dovrebbero arrivare in meno di un giorno. Non voglio vedere uno di quegli insetti scavare fin dentro la mia miniera, quindi spero che qualcuno si stia prendendo il tempo di assemblare lo Scettro delle Sabbie Mutevoli, così che il gong possa suonare, i cancelli si aprano e la guerra abbia finalmente inizio.", "." },
  ["9a843b57cdf9088c"] = { "Il Suo controllo su di te è spezzato. E anche se gli esseri inferiori ti giudicheranno, almeno hai possibilità che il Flagello non ha!", "." },
  ["9a8bf33dc24d684a"] = { "Nemico avvistato! Fuoco!", "." },
  ["9a9053de925d4f6b"] = { "DOOMHAMMER, GUIDA LA MIA MANO!", "." },
  ["9a9499dca2fac1a7"] = { "Grazie, Charys. Vieni, Paige, tesoro.", "." },
  ["9a9a6b97846a04b4"] = { "Impari in fretta, <ragazzo/ragazza>, molto più in fretta di quanto riesca a starti dietro. Se vuoi continuare l'addestramento, ti consiglio di andare dal mio maestro. Si chiama Rotgath, ⟦Rotgath Stonebeard=Rotgath Barbapietra⟧, e lo trovi a ⟦Ironforge=Forgiardente⟧, nella ⟦Great Forge=Grande Forgia⟧.", "." },
  ["9a9b5405016f36ae"] = { "Il Flagello ti chiama, <stolto/stolta> {race}.", "." },
  ["9aa2b086abc822e1"] = { "Questo ponte non sarà mai finito, vero?", "." },
  ["9aacb88697285231"] = { "Sì, davvero! <PH>", "." },
  ["9aad7ad8d52a4565"] = { "È ciò che volevo sapere. Ora devo solo trovare dove si parla della varianza del flusso.", "." },
  ["9ab188d82333e622"] = { "Non è una menzogna, traditore. Banehollow vuole il tuo cuore, e io glielo porterò.", "." },
  ["9abf65bdba0a5feb"] = { "Fino ad allora, prendo congedo...", "." },
  ["9ac326735b36029f"] = { "Preparati ad affrontare il tuo destino!", "." },
  ["9ac9ebb367c1fb23"] = { "Non merito tanto, <signore/signora>.", "." },
  ["9aca7f097eef1138"] = { "SONO QUI VICINO!", "." },
  ["9ad10c3fe0187b0a"] = { "%s si schiude!", "." },
  ["9ad2ec2ae065d566"] = { "Benvenut<o/a> nella mia bottega. Cosa posso fare per te?", "." },
  ["9ad864a1d74d3d23"] = { "Ti ho dato una Pietra del Giuramento dello Stormo di Ysera, {name}. Quando te la sentirai e potrai aiutarci, usala, e allora potremo cominciare.", "." },
  ["9ae4b040d9993ae8"] = { "Non ho tempo da perdere con quelli come te, {class}.", "." },
  ["9ae61f4ffeb52ff1"] = { "Wow, tutto questo per un filtro d'amore. Spero che ne valga la pena.", "." },
  ["9ae8536442f19a09"] = { "Grazie agli sforzi congiunti delle gilde di avventurieri dell'Alleanza, siamo riusciti a raccogliere tutte le pietre del nucleo carbonizzate che pensiamo ci serviranno. Tuttavia, potresti chiedere agli altri raccoglitori qui intorno se hanno ancora bisogno di aiuto per raccogliere risorse vitali.", "." },
  ["9aeb3f33b35c3b1a"] = { "Il generale dell'⟦Horde=Orda⟧ è stato sconfitto!\n\nL'⟦Alliance=Alleanza⟧ ha vinto, e ora l'⟦Horde=Orda⟧ si affanna a ricostruire le sue forze indebolite.", "." },
  ["9aec5a50e1f2ba36"] = { "Tiene un rametto di vischio sopra la testa", "." },
  ["9af20e90f2d2ee8d"] = { "Ormai è tutto finito, resta solo da piangere. Tutto il materiale bellico viene trasportato alla ⟦Cenarion Hold=Fortezza Cenariana⟧, a ⟦Silithus=Silitus⟧, e l'ultima parte arriverà in meno di un giorno. Non dovrebbe mancare molto prima che lo scettro venga assemblato e la guerra abbia finalmente inizio.", "." },
  ["9af7eb5d3a3d00e8"] = { "La Stormpike Aid Station si trova a Dun Baldar, proprio fuori dalla caserma di Dun Baldar.\n\nAl momento è controllata dall'⟦Alliance=Alleanza⟧.", "." },
  ["9af915dfc93f4262"] = { "Ho finito di esaminare i teschi, {name}, e che sollievo: Yenniku non è tra loro...", "." },
})
